  const r = await f.show(p);
  if (r.canceled || !r.formValues || !p.isValid) return;
  const on = MODS.filter((x, i) => r.formValues[i]).map((x) => x[0]), why = engine.command(p, 'mods', on.length ? on : ['none']);
